<?php
namespace App\Http\Controllers\Tenant\Api\V1;use App\Http\Controllers\Controller;use App\Models\Customer\Contact;use App\Models\Inbox\Conversation;use App\Models\Ticket\Ticket;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class ResourceController extends Controller{private function size(Request $r):int{return min(100,max(1,$r->integer('per_page',25)));}public function contacts(Request $r):JsonResponse{return response()->json(Contact::query()->select(['public_uuid','display_name','email','phone','status','preferred_language','country','created_at','updated_at'])->orderBy('id')->cursorPaginate($this->size($r)));}public function conversations(Request $r):JsonResponse{return response()->json(Conversation::with(['contact:id,public_uuid,display_name','channel:id,name,type','assignee:id,name','team:id,name'])->select(['id','public_uuid','contact_id','channel_id','assignee_id','team_id','subject','status','priority','last_message_at','created_at','updated_at'])->orderBy('id')->cursorPaginate($this->size($r)));}public function tickets(Request $r):JsonResponse{return response()->json(Ticket::with(['contact:id,public_uuid,display_name','status:id,name,category','assignee:id,name','team:id,name'])->select(['id','public_uuid','ticket_number','subject','contact_id','status_id','assignee_id','team_id','priority','created_at','updated_at'])->orderBy('id')->cursorPaginate($this->size($r)));}}
